import { describe, expect, it } from "vitest";

import { runReit } from "../application/run-reit";
import { fixtureReitValuation } from "../infrastructure/fixture-reit-valuation";
import { divide, formatDecimal, ONE, parseDecimal } from "./decimal-policy";
import { financialCostOfEquity } from "./excess-return";
import { reconcileAffo } from "./reit";

const dependencies = {
  now: () => "2026-10-20T15:00:00.000Z",
  newValuationRunId: () => "11111111-2222-4333-8444-555555555555",
};

/** Expected cells transcribed from reval.xls, not generated by this engine.
 * Workbook hash, cells and convention differences: docs/valuation/reit-oracle.md. */
describe("REIT independent financial references", () => {
  it.each([
    [
      "C",
      "709047.572890916",
      "1545000",
      "2709047.57289092",
      "1164047.57289092",
    ],
    [
      "D",
      "898737.627256306",
      "1591350",
      "2898737.62725631",
      "1307387.62725631",
    ],
    [
      "E",
      "1094831.00581709",
      "1639090.5",
      "3094831.00581709",
      "1455740.50581709",
    ],
    [
      "F",
      "1297534.04622699",
      "1688263.215",
      "3297534.04622699",
      "1609270.83122699",
    ],
    [
      "G",
      "1507059.41777721",
      "1738911.11145",
      "3507059.41777721",
      "1768148.30632721",
    ],
  ])(
    "matches equity cash in reval.xls column %s",
    (_column, netIncome, maintenance, ffo, equityCash) => {
      const input = fixtureReitValuation();
      input.affo.commonNetIncome!.value = netIncome!;
      input.affo.realEstateDepreciation!.value = "2000000";
      input.affo.recurringCapex!.value = maintenance!;
      for (const key of [
        "propertySaleGains",
        "realEstateImpairments",
        "jointVentureAdjustment",
        "straightLineRent",
      ] as const)
        input.affo[key]!.value = "0";
      const actual = reconcileAffo(input);
      expect(
        actual.ffo
          .minus(parseDecimal(ffo!, "expected.ffo"))
          .abs()
          .lt("0.0000001"),
      ).toBe(true);
      expect(
        actual.affo
          .minus(parseDecimal(equityCash!, "expected.cash"))
          .abs()
          .lt("0.0000001"),
      ).toBe(true);
      input.risk.riskFree!.value = "0.054";
      input.risk.matureErp!.value = "0.04";
      expect(formatDecimal(financialCostOfEquity(input, "1.1966"), "ke")).toBe(
        "0.101864",
      );
    },
  );

  it("matches the sheet's NOI multiple with its reciprocal capitalization rate", () => {
    const input = fixtureReitValuation();
    input.assumptions.nav.forwardNoi = "6107405";
    input.assumptions.nav.capRate = formatDecimal(
      divide(ONE, parseDecimal("13.3396058855002", "multiple"), "cap"),
      "cap",
    );
    const result = runReit(input, dependencies).result!;
    expect(
      parseDecimal(result.base.nav.propertyValue, "propertyValue")
        .minus("81470375.6831332")
        .abs()
        .lt("0.000001"),
    ).toBe(true);
  });

  it("matches a growing perpetuity with funded growth, regardless of explicit horizon", () => {
    // AFFO0=10, growth=2%, return on incremental equity=12%, Ke=10%.
    // Cash1=10*1.02*(1-1/6)=8.5; equity=8.5/(.10-.02)=106.25.
    for (const horizon of [1, 2, 5, 10, 20]) {
      const input = fixtureReitValuation();
      input.scenarios = null;
      input.sensitivity = null;
      input.assumptions.periods = Array.from({ length: horizon }, () => ({
        ...input.assumptions.periods[0]!,
      }));
      const result = runReit(input, dependencies).result!.base;
      expect(
        parseDecimal(result.grossEquityValue, "equity")
          .minus("106.25")
          .abs()
          .lt("0.000000000000000000000000001"),
      ).toBe(true);
      expect(Number(result.valuePerShare)).toBeCloseTo(10.625, 12);
    }
  });

  it("keeps the multiple of forward AFFO at 1/Ke when incremental returns equal Ke", () => {
    for (const growth of ["0", "0.01", "0.02", "0.03"]) {
      const input = fixtureReitValuation();
      input.scenarios = null;
      input.assumptions.periods.forEach((p) => {
        p.affoGrowth = growth;
        p.returnOnNewEquity = "0.1";
      });
      input.assumptions.terminal.growth = growth;
      input.assumptions.terminal.returnOnNewEquity = "0.1";
      expect(
        Number(runReit(input, dependencies).result!.base.grossEquityValue),
      ).toBeCloseTo(100 * (1 + Number(growth)), 12);
    }
  });
});
